PRAGMA foreign_keys=ON;
CREATE TABLE clientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, telefono TEXT NOT NULL);
CREATE TABLE mascotas (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, especie TEXT NOT NULL, raza TEXT, fecha_nacimiento TEXT NOT NULL, id_cliente INTEGER NOT NULL REFERENCES clientes(id) ON DELETE RESTRICT);
CREATE TABLE veterinarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, especialidad TEXT NOT NULL, tarifa_hora NUMERIC NOT NULL CHECK(tarifa_hora >= 0));
CREATE TABLE consultas (id INTEGER PRIMARY KEY AUTOINCREMENT, id_mascota INTEGER NOT NULL REFERENCES mascotas(id) ON DELETE RESTRICT, id_veterinario INTEGER NOT NULL REFERENCES veterinarios(id) ON DELETE RESTRICT, fecha TEXT NOT NULL, horas NUMERIC NOT NULL CHECK(horas > 0), estado TEXT NOT NULL CHECK(estado IN ('PROGRAMADA','EN_CURSO','FINALIZADA')));
CREATE TABLE tratamientos (id INTEGER PRIMARY KEY AUTOINCREMENT, id_consulta INTEGER NOT NULL REFERENCES consultas(id) ON DELETE RESTRICT, descripcion TEXT NOT NULL, cantidad INTEGER NOT NULL CHECK(cantidad > 0), precio_unitario NUMERIC NOT NULL CHECK(precio_unitario >= 0));
